def find_Nth_Digit(numerator, denominator, nth_digit):
  numerator_str = str(numerator)
  denominator_str = str(denominator)
  total_length = len(numerator_str) + len(denominator_str)
  quotient = numerator // denominator
  remainder = numerator % denominator
  position_in_numerator = total_length - len(str(quotient))
  position_in_denominator = total_length - len(str(remainder))
  if position_in_numerator >= nth_digit:
    return int(numerator_str[position_in_numerator - 1])
  else:
    return int(denominator_str[position_in_denominator - 1])

