      dp[0][j] = grid[0][j]
  
  # Fill the DP table
  for i in range(1, rows):
      for j in range(cols):
          if j == 0:
              dp[i][j] = dp[i-1][j] + grid[i][j]
          elif j == cols - 1:
              dp[i][j] = dp[i-1][j] + grid[i][j]
